#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 11) {
        cout << 0 << "\n";
        return 0;
    }
    vector<vector<int>> coordinates(n, vector<int>(5));
    vector<vector<vector<long long>>> vectors(n, vector<vector<long long>>(n, vector<long long>(5, 0)));
    vector<bool> eliminated(n, false);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 5; j++) {
            cin >> coordinates[i][j];
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < 5; k++) {
                vectors[i][j][k] = (long long)coordinates[j][k] - (long long)coordinates[i][k];
            }
        }
    }
    int remainingCount = n;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j != i) {
                for (int k = 0; k < n; k++) {
                    if (k != j && k != i) {
                        long long dotProduct = 0;
                        for (int m = 0; m < 5; m++) {
                            dotProduct += vectors[j][i][m] * vectors[k][i][m];
                        }
                        if (dotProduct > 0 && !eliminated[i]) {
                            eliminated[i] = true;
                            remainingCount--;
                        }
                    }
                }
            }
        }
    }
    cout << remainingCount << "\n";
    for (int i = 0; i < n; i++) {
        if (!eliminated[i]) {
            cout << (i + 1) << "\n";
        }
    }
    return 0;
}
